import{_ as t,c as e,o as r,ag as l}from"./chunks/framework.CMajxlqO.js";const p=JSON.parse('{"title":"PLCSIM - PLC-simulering","description":"","frontmatter":{},"headers":[],"relativePath":"09-test-simulering/plcsim.md","filePath":"09-test-simulering/plcsim.md","lastUpdated":1768470380000}'),i={name:"09-test-simulering/plcsim.md"};function n(s,a,o,d,g,c){return r(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="plcsim-plc-simulering" tabindex="-1">PLCSIM - PLC-simulering <a class="header-anchor" href="#plcsim-plc-simulering" aria-label="Permalink to &quot;PLCSIM - PLC-simulering&quot;">​</a></h1><p>S7-PLCSIM är ett simuleringsverktyg som ingår i TIA Portal och låter dig testa PLC-program utan fysisk hårdvara. Detta är ovärderligt för att verifiera programlogik innan idrifttagning.</p><h2 id="vad-ar-s7-plcsim" tabindex="-1">Vad är S7-PLCSIM? <a class="header-anchor" href="#vad-ar-s7-plcsim" aria-label="Permalink to &quot;Vad är S7-PLCSIM?&quot;">​</a></h2><p>S7-PLCSIM skapar en virtuell PLC i datorn som beter sig som en riktig S7-1200 eller S7-1500. Du kan:</p><ul><li>Ladda ner och köra program</li><li>Testa logik och sekvenser</li><li>Simulera in- och utgångar</li><li>Använda watch tables för övervakning</li><li>Testa HMI-kopplingar</li></ul><div class="tip custom-block"><p class="custom-block-title">Fördelar med simulering</p><ul><li>Ingen risk att skada utrustning</li><li>Testa parallellt med utveckling</li><li>Felsök program innan idrifttagning</li><li>Utbilda personal säkert</li></ul></div><h2 id="starta-plcsim" tabindex="-1">Starta PLCSIM <a class="header-anchor" href="#starta-plcsim" aria-label="Permalink to &quot;Starta PLCSIM&quot;">​</a></h2><h3 id="steg-1-ladda-ner-projekt" tabindex="-1">Steg 1: Ladda ner projekt <a class="header-anchor" href="#steg-1-ladda-ner-projekt" aria-label="Permalink to &quot;Steg 1: Ladda ner projekt&quot;">​</a></h3><ol><li>Öppna ditt TIA Portal-projekt</li><li>Markera din PLC i projektträdet</li><li>Klicka på <strong>Download to device</strong> (eller Ctrl+L)</li><li>Välj <strong>Start simulation</strong> i dialogrutan</li></ol><h3 id="steg-2-plcsim-granssnitt" tabindex="-1">Steg 2: PLCSIM-gränssnitt <a class="header-anchor" href="#steg-2-plcsim-granssnitt" aria-label="Permalink to &quot;Steg 2: PLCSIM-gränssnitt&quot;">​</a></h3><p>När PLCSIM startar öppnas ett eget fönster med:</p><ul><li><strong>SIM table</strong> - Simulera in/utgångar</li><li><strong>Sequence</strong> - Spela in och spela upp sekvenser</li><li><strong>Control panel</strong> - RUN/STOP-knapp, LED-indikatorer</li></ul><h3 id="steg-3-satt-plc-i-run" tabindex="-1">Steg 3: Sätt PLC i RUN <a class="header-anchor" href="#steg-3-satt-plc-i-run" aria-label="Permalink to &quot;Steg 3: Sätt PLC i RUN&quot;">​</a></h3><ol><li>Klicka på <strong>RUN</strong> i PLCSIM Control Panel</li><li>Verifiera att RUN-LED lyser grönt</li><li>Programmet körs nu i simulatorn</li></ol><h2 id="watch-tables-overvaka-variabler" tabindex="-1">Watch Tables - Övervaka variabler <a class="header-anchor" href="#watch-tables-overvaka-variabler" aria-label="Permalink to &quot;Watch Tables - Övervaka variabler&quot;">​</a></h2><p>Watch tables låter dig se och ändra variabelvärden i realtid.</p><h3 id="skapa-en-watch-table" tabindex="-1">Skapa en watch table <a class="header-anchor" href="#skapa-en-watch-table" aria-label="Permalink to &quot;Skapa en watch table&quot;">​</a></h3><ol><li>Högerklicka på <strong>Watch and force tables</strong> i projektträdet</li><li>Välj <strong>Add new watch table</strong></li><li>Lägg till de variabler du vill övervaka</li></ol><h3 id="funktioner-i-watch-table" tabindex="-1">Funktioner i watch table <a class="header-anchor" href="#funktioner-i-watch-table" aria-label="Permalink to &quot;Funktioner i watch table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Funktion</th><th>Beskrivning</th></tr></thead><tbody><tr><td><strong>Monitor</strong></td><td>Visa aktuella värden</td></tr><tr><td><strong>Modify</strong></td><td>Ändra värden tillfälligt</td></tr><tr><td><strong>Force</strong></td><td>Tvinga värden (överskrider program)</td></tr></tbody></table><h3 id="exempel-overvaka-motorkontroll" tabindex="-1">Exempel: Övervaka motorkontroll <a class="header-anchor" href="#exempel-overvaka-motorkontroll" aria-label="Permalink to &quot;Exempel: Övervaka motorkontroll&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Adress          | Displayformat | Modifiera</span></span>
<span class="line"><span>----------------|---------------|----------</span></span>
<span class="line"><span>%I0.0           | BOOL          | TRUE</span></span>
<span class="line"><span>%Q0.0           | BOOL          | -</span></span>
<span class="line"><span>&quot;DB1&quot;.Motor_On  | BOOL          | -</span></span>
<span class="line"><span>&quot;DB1&quot;.Hastighet | REAL          | 50.0</span></span></code></pre></div><h2 id="force-values-tvinga-varden" tabindex="-1">Force Values - Tvinga värden <a class="header-anchor" href="#force-values-tvinga-varden" aria-label="Permalink to &quot;Force Values - Tvinga värden&quot;">​</a></h2><p>Force är kraftfullt men ska användas med försiktighet:</p><div class="warning custom-block"><p class="custom-block-title">Varning</p><p>Force-värden överskrider all programlogik! En forcerad utgång förblir i sitt läge oavsett vad programmet gör. Glöm aldrig att ta bort force innan verklig drift.</p></div><h3 id="anvanda-force" tabindex="-1">Använda Force <a class="header-anchor" href="#anvanda-force" aria-label="Permalink to &quot;Använda Force&quot;">​</a></h3><ol><li>Högerklicka på värdet i watch table</li><li>Välj <strong>Force to 1</strong> eller <strong>Force to 0</strong></li><li>Forcerade värden visas med speciell ikon</li><li>Ta bort med <strong>Delete force</strong> eller <strong>Stop forcing</strong></li></ol><h2 id="sim-table-simulera-i-o" tabindex="-1">SIM Table - Simulera I/O <a class="header-anchor" href="#sim-table-simulera-i-o" aria-label="Permalink to &quot;SIM Table - Simulera I/O&quot;">​</a></h2><p>SIM table låter dig simulera ingångar som om de vore riktiga sensorer.</p><h3 id="lagga-till-ingangar" tabindex="-1">Lägga till ingångar <a class="header-anchor" href="#lagga-till-ingangar" aria-label="Permalink to &quot;Lägga till ingångar&quot;">​</a></h3><ol><li>Klicka i <strong>Address</strong>-kolumnen</li><li>Skriv adressen (t.ex. <code>%I0.0</code>)</li><li>Klicka på checkboxen för att ändra värde</li></ol><h3 id="simulera-analoga-ingangar" tabindex="-1">Simulera analoga ingångar <a class="header-anchor" href="#simulera-analoga-ingangar" aria-label="Permalink to &quot;Simulera analoga ingångar&quot;">​</a></h3><p>För analoga värden (t.ex. temperatur):</p><ol><li>Lägg till adressen <code>%IW64</code> (analogt inords)</li><li>Ange värdet i decimalformat</li><li>Programmet läser det simulerade värdet</li></ol><h2 id="debugging-funktioner" tabindex="-1">Debugging-funktioner <a class="header-anchor" href="#debugging-funktioner" aria-label="Permalink to &quot;Debugging-funktioner&quot;">​</a></h2><h3 id="breakpoints" tabindex="-1">Breakpoints <a class="header-anchor" href="#breakpoints" aria-label="Permalink to &quot;Breakpoints&quot;">​</a></h3><p>Du kan pausa programmet vid specifika instruktioner:</p><ol><li>Öppna programblocket</li><li>Klicka i marginalen vid önskad rad</li><li>En röd punkt markerar breakpoint</li><li>Programmet stannar när det når denna punkt</li></ol><h3 id="single-step" tabindex="-1">Single Step <a class="header-anchor" href="#single-step" aria-label="Permalink to &quot;Single Step&quot;">​</a></h3><p>Stega igenom programmet rad för rad:</p><ol><li>Sätt en breakpoint</li><li>När programmet pausar, använd <strong>Step Into</strong> (F11)</li><li>Analysera variabelvärden mellan varje steg</li></ol><h3 id="call-hierarchy" tabindex="-1">Call Hierarchy <a class="header-anchor" href="#call-hierarchy" aria-label="Permalink to &quot;Call Hierarchy&quot;">​</a></h3><p>Se vilka block som anropas:</p><ol><li>Högerklicka på ett block</li><li>Välj <strong>Show call structure</strong></li><li>Diagrammet visar anropskedjan</li></ol><h2 id="tips-for-effektiv-simulering" tabindex="-1">Tips för effektiv simulering <a class="header-anchor" href="#tips-for-effektiv-simulering" aria-label="Permalink to &quot;Tips för effektiv simulering&quot;">​</a></h2><h3 id="forbereda-for-test" tabindex="-1">Förbereda för test <a class="header-anchor" href="#forbereda-for-test" aria-label="Permalink to &quot;Förbereda för test&quot;">​</a></h3><ol><li>Skapa en <strong>testplan</strong> med scenarion att verifiera</li><li>Dokumentera förväntade resultat</li><li>Använd descriptive taggnamn för enklare övervakning</li></ol><h3 id="vanliga-testfall" tabindex="-1">Vanliga testfall <a class="header-anchor" href="#vanliga-testfall" aria-label="Permalink to &quot;Vanliga testfall&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scenario</th><th>Vad testa</th></tr></thead><tbody><tr><td>Normal drift</td><td>Sekvens fungerar korrekt</td></tr><tr><td>Felfall</td><td>Larm och säkerhetsstopp</td></tr><tr><td>Gränsvärden</td><td>Min/max-värden hanteras</td></tr><tr><td>Timeout</td><td>Tidövervakning fungerar</td></tr></tbody></table><h3 id="spara-testsekvenser" tabindex="-1">Spara testsekvenser <a class="header-anchor" href="#spara-testsekvenser" aria-label="Permalink to &quot;Spara testsekvenser&quot;">​</a></h3><p>PLCSIM kan spara och spela upp ingångssekvenser:</p><ol><li>Gå till <strong>Sequence</strong> i PLCSIM</li><li>Klicka <strong>Record</strong></li><li>Utför sekvensen manuellt</li><li>Klicka <strong>Stop</strong> och <strong>Save</strong></li><li>Spela upp med <strong>Play</strong></li></ol><h2 id="plcsim-vs-plcsim-advanced" tabindex="-1">PLCSIM vs PLCSIM Advanced <a class="header-anchor" href="#plcsim-vs-plcsim-advanced" aria-label="Permalink to &quot;PLCSIM vs PLCSIM Advanced&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Funktion</th><th>PLCSIM</th><th>PLCSIM Advanced</th></tr></thead><tbody><tr><td>Ingår i TIA Portal</td><td>Ja</td><td>Separat licens</td></tr><tr><td>S7-1200</td><td>Ja</td><td>Ja</td></tr><tr><td>S7-1500</td><td>Ja</td><td>Ja</td></tr><tr><td>Flera instanser</td><td>Nej</td><td>Ja</td></tr><tr><td>OPC UA</td><td>Nej</td><td>Ja</td></tr><tr><td>Virtual Ethernet</td><td>Nej</td><td>Ja</td></tr><tr><td>Webserver</td><td>Nej</td><td>Ja</td></tr></tbody></table><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/109795016/simatic-s7-plcsim-advanced-v4.0-download-incl.-trial-license" target="_blank" rel="noreferrer">S7-PLCSIM Advanced V4.0</a> - Trial-nedladdning och dokumentation</li><li><a href="https://support.industry.siemens.com/cs/document/109817218/updates-for-step-7-v18-s7-plcsim-v18-and-wincc-v18" target="_blank" rel="noreferrer">TIA Portal V18 Updates</a> - Uppdateringar för TIA V18 och PLCSIM</li></ul><h2 id="nasta-steg" tabindex="-1">Nästa steg <a class="header-anchor" href="#nasta-steg" aria-label="Permalink to &quot;Nästa steg&quot;">​</a></h2><ul><li><a href="./hmi-simulering.html">HMI-simulering</a> - Testa operatörspaneler</li><li><a href="./kommunikationskontroll.html">Kommunikationskontroll</a> - Diagnostisera kommunikation</li></ul>`,59)])])}const u=t(i,[["render",n]]);export{p as __pageData,u as default};
